const CATEGORY_META={
  "Zuivel":["🥛","Zuivel"],"Kaas":["🧀","Kaas"],"Ei":["🥚","Ei"],"Groenten":["🥕","Groenten"],"Fruit":["🍌","Fruit"],
  "Vlees":["🥩","Vlees"],"Vis":["🐟","Vis"],"Noten":["🥜","Noten"],"Pitten & zaden":["🌱","Pitten & zaden"],
  "Granen & wafels":["🌾","Granen & wafels"],"Peulvruchten":["🫘","Peulvruchten"],"Proteïne":["💪","Proteïne"],
  "Olie & vet":["🫒","Olie & vet"],"Extra's":["🍯","Extra's"]
};
const NORMAL_MEALS=[["breakfast","Ontbijt","☀️"],["lunch","Lunch","🥗"],["dinner","Diner","🍽️"],["snack","Tussendoor","🍎"]];
const FAST_MEALS=[["suhoor","Suhoor","🌙"],["futoor","Futoor","🌅"]];
const ALL_MEALS=[...NORMAL_MEALS,...FAST_MEALS];
const LS='balance.v1';
const DEFAULTS={
  version:2,
  goals:{kcal:2200,protein:140,carbs:220,fat:70,fiber:30,water:2500,steps:10000,restingBurn:1500,activeDeduction:20,targetWeight:null,netCarbs:false},
  weekGoals:{}, fastingDays:{}, foods:[],productOverrides:{},hiddenProducts:[],logs:{},plannedMeals:[],activity:{},water:{},waterLogs:{},workouts:[],weights:[],recipes:[],favorites:[],recent:[],settings:{showSourceBadges:true},draft:null
};
let state=loadState();
let route={name:'home',params:{}};

function clone(x){return JSON.parse(JSON.stringify(x));}
function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d;}
function f(v,dec=0){return n(v).toLocaleString('nl-NL',{maximumFractionDigits:dec,minimumFractionDigits:dec});}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function uid(p='id'){return p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);}
function todayISO(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`;}
function dateObj(iso){return new Date(iso+'T12:00:00');}
function addDaysISO(iso,days){const d=dateObj(iso);d.setDate(d.getDate()+days);return todayISO(d);}
function fmtDate(iso,long=false){return dateObj(iso).toLocaleDateString('nl-NL',long?{weekday:'long',day:'numeric',month:'long'}:{weekday:'short',day:'numeric',month:'short'});}
function fmtTime(d=new Date()){return d.toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'});}
function weekStartISO(iso=todayISO()){const d=dateObj(iso);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return todayISO(d);}
function weekDates(iso){const s=weekStartISO(iso);return Array.from({length:7},(_,i)=>addDaysISO(s,i));}
function weekNumber(iso){const d=dateObj(iso);d.setHours(0,0,0,0);d.setDate(d.getDate()+3-((d.getDay()+6)%7));const w1=new Date(d.getFullYear(),0,4);return 1+Math.round(((d-w1)/86400000-3+((w1.getDay()+6)%7))/7);}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2300);}
function save(){localStorage.setItem(LS,JSON.stringify(state));}
function loadState(){
  try{
    const raw=localStorage.getItem(LS);if(!raw)return clone(DEFAULTS);
    const x=JSON.parse(raw);const s={...clone(DEFAULTS),...x,goals:{...DEFAULTS.goals,...(x.goals||{})},settings:{...DEFAULTS.settings,...(x.settings||{})}};
    s.weekGoals=s.weekGoals||{};s.fastingDays=s.fastingDays||{};s.plannedMeals=s.plannedMeals||[];s.waterLogs=s.waterLogs||{};s.productOverrides=s.productOverrides||{};s.hiddenProducts=s.hiddenProducts||[];
    // migrate old one-number water totals without deleting old data
    for(const [iso,total] of Object.entries(s.water||{})){if(n(total)>0&&!s.waterLogs[iso]?.length)s.waterLogs[iso]=[{id:uid('water'),ml:n(total),time:'—',migrated:true}];}
    return s;
  }catch(e){return clone(DEFAULTS);}
}
function allProducts(){const hidden=new Set(state.hiddenProducts||[]);const seeds=SEED_PRODUCTS.filter(p=>!hidden.has(p.id)).map(p=>state.productOverrides[p.id]?{...p,...state.productOverrides[p.id],custom:false,edited:true}:p);return [...seeds,...(state.foods||[]).filter(p=>!hidden.has(p.id))];}
function productById(id){return allProducts().find(p=>p.id===id);}
function amountSnapshot(p,amount){const z=n(amount)/100;return {kcal:n(p.kcal)*z,protein:n(p.protein)*z,carbs:n(p.carbs)*z,fat:n(p.fat)*z,fiber:n(p.fiber)*z,sugars:n(p.sugars)*z,satFat:n(p.satFat)*z,salt:n(p.salt)*z};}
function macros(entries){return (entries||[]).reduce((a,e)=>{for(const k of ['kcal','protein','carbs','fat','fiber'])a[k]+=n(e.snapshot?.[k]);return a;},{kcal:0,protein:0,carbs:0,fat:0,fiber:0});}
function mealMeta(k){return ALL_MEALS.find(x=>x[0]===k)||[k,k,'🍽️'];}
function mealsForDate(iso){return isFasting(iso)?FAST_MEALS:NORMAL_MEALS;}
function isFasting(iso){return !!state.fastingDays?.[iso];}
function getDay(iso){if(!state.logs[iso])state.logs[iso]={};return state.logs[iso];}
function entriesFor(iso,meal){return state.logs[iso]?.[meal]||[];}
function allActualEntries(iso){return Object.values(state.logs[iso]||{}).flat();}
function dayMacros(iso){return macros(allActualEntries(iso));}
function plannedForDate(iso){return (state.plannedMeals||[]).filter(p=>p.date===iso);}
function plannedMacros(iso){return macros(plannedForDate(iso).filter(p=>p.status!=='cancelled').flatMap(p=>p.items||[]));}
function activityFor(iso){return state.activity[iso]||{steps:0,activeKcal:0};}
function weekGoal(iso){const wk=weekStartISO(iso);return state.weekGoals[wk]||null;}
function effectiveGoals(iso){return {...state.goals,...(weekGoal(iso)||{})};}
function energyFor(iso){const m=dayMacros(iso),a=activityFor(iso),g=effectiveGoals(iso);const corrected=n(a.activeKcal)*(1-n(g.activeDeduction)/100);const burn=n(g.restingBurn)+corrected;return {intake:m.kcal,corrected,burn,balance:m.kcal-burn};}
function waterEntries(iso){return state.waterLogs[iso]||[];}
function waterTotal(iso){return waterEntries(iso).reduce((s,x)=>s+n(x.ml),0);}
function conversionFactor(p){const s=(p.name+' '+p.state).toLowerCase();if(s.includes('rijst'))return 2.6;if(s.includes('quinoa'))return 3.5;if(s.includes('bulgur'))return 3.5;if(s.includes('couscous'))return 3;if(p.category==='Peulvruchten'&&!/blik|pot|diepvries|uitlek/.test(s))return 2.5;return null;}
function conversionText(p,amount){const fac=conversionFactor(p);if(!fac||!amount)return '';const st=(p.state||'').toLowerCase();if(/droog|onbereid/.test(st))return `${f(amount,1)} g droog ≈ ${f(amount*fac,0)} g bereid (richtwaarde ×${String(fac).replace('.',',')})`;if(/gekookt|bereid/.test(st))return `${f(amount,1)} g bereid ≈ ${f(amount/fac,1)} g droog equivalent`;return '';}

function currentDate(){return route.params.date||todayISO();}
function routeTo(name,params={}){route={name,params};history.replaceState(null,'','#'+name);render();scrollTo(0,0);}
function setHeader(title,actions=''){document.getElementById('headerSubtitle').textContent=title;document.getElementById('headerActions').innerHTML=actions;}
function setActiveNav(name){document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.route===(name==='today'?'home':name)||(name.startsWith('builder')&&b.dataset.route==='add')));}
function render(){setActiveNav(route.name);const fn={home:renderHome,today:renderHome,agenda:renderAgenda,add:renderAddStart,builder:renderBuilder,builderCategory:renderBuilderCategory,cart:renderCart,weight:renderWeight,more:renderMore,products:renderProducts,recipes:renderRecipes,trends:renderTrends,goals:renderGoals,history:renderHistory,settings:renderSettings}[route.name]||renderHome;document.getElementById('view').innerHTML=fn();bindDynamic();maybePromptWeek();}

function kpi(label,val,goal,unit){const pct=Math.min(100,n(val)/Math.max(1,n(goal))*100);return `<div class="kpi"><span class="subtle">${label}</span><strong>${f(val,0)}${unit}</strong><div class="progress"><span style="width:${pct}%"></span></div><small>${f(goal,0)}${unit} doel</small></div>`;}
function shiftHome(delta){route.params.date=addDaysISO(currentDate(),delta);render();}
function dayAgendaItems(iso){
  const out=[];
  for(const p of plannedForDate(iso)){out.push({time:p.time||'',icon:mealMeta(p.meal)[2],title:p.name||mealMeta(p.meal)[1],meta:`${f(macros(p.items).kcal)} kcal · ${p.status==='completed'?'uitgevoerd':'gepland'}`,kind:'meal',id:p.id});}
  for(const w of (state.workouts||[]).filter(w=>w.date===iso)){out.push({time:w.time||'',icon:w.type==='kickboksen'?'🥊':'🏋️',title:w.title,meta:`${f(w.duration)} min · ${w.status||'gepland'}`,kind:'workout',id:w.id});}
  return out.sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));
}
function renderHome(){
  const iso=currentDate(),m=dayMacros(iso),pm=plannedMacros(iso),e=energyFor(iso),a=activityFor(iso),g=effectiveGoals(iso),water=waterTotal(iso),fast=isFasting(iso),agenda=dayAgendaItems(iso);
  setHeader(iso===todayISO()?'Home · Vandaag':`Home · ${fmtDate(iso)}`,`<button class="icon-btn" id="datePrev">‹</button><button class="icon-btn" id="dateNext">›</button>`);
  const bal=e.balance<0?`${f(Math.abs(e.balance))} kcal tekort`:`${f(e.balance)} kcal overschot`;
  const actualMealKeys=Object.keys(state.logs[iso]||{});
  return `<section class="section card hero"><div class="section-title"><h2>Energiebalans</h2><span class="badge">schatting</span></div>
    <div class="metric"><span>Caloriedoel</span><b>${f(g.kcal)} kcal</b></div><div class="metric"><span>Gegeten</span><b>${f(m.kcal)} kcal</b></div><div class="metric"><span>Gepland</span><b>${f(pm.kcal)} kcal</b></div><div class="metric"><span>Geschatte verbranding</span><b>${f(e.burn)} kcal</b></div><div class="metric"><span>Balans werkelijk</span><b>${bal}</b></div>
    <div class="kpi-row">${kpi('Eiwit',m.protein,g.protein,'g')}${kpi('KH',m.carbs,g.carbs,'g')}${kpi('Vet',m.fat,g.fat,'g')}${kpi('Vezels',m.fiber,g.fiber,'g')}</div></section>
    ${fast?`<section class="section"><div class="fast-banner">🌙 <div><b>Vastendag</b><div class="subtle">Deze dag gebruikt Suhoor en Futoor.</div></div><button class="secondary" data-fast-toggle="${iso}">Uitschakelen</button></div></section>`:''}
    <section class="section"><div class="section-title"><h2>Dagagenda</h2><button class="ghost-btn" data-agendadate="${iso}">Open agenda</button></div>${agenda.length?`<div class="list">${agenda.map(x=>`<div class="list-item"><div class="timeline-row"><span class="time">${esc(x.time||'—')}</span><span class="event-icon">${x.icon}</span><div><b>${esc(x.title)}</b><div class="meta">${esc(x.meta)}</div></div></div></div>`).join('')}</div>`:`<div class="card empty"><span class="big">📅</span>Nog niets gepland voor deze dag.</div>`}</section>
    <section class="section"><div class="section-title"><h2>Maaltijden</h2><button class="ghost-btn" data-addmealdate="${iso}">＋ toevoegen</button></div><div class="grid">${mealsForDate(iso).map(mm=>mealCard(iso,mm)).join('')}${actualMealKeys.filter(k=>!mealsForDate(iso).some(m=>m[0]===k)).map(k=>mealCard(iso,mealMeta(k))).join('')}</div></section>
    <section class="section grid two"><div class="card"><div class="section-title"><h2>Water</h2><span>💧</span></div><div style="font-size:28px;font-weight:800">${f(water)} ml</div><div class="progress" style="margin:8px 0"><span style="width:${Math.min(100,water/Math.max(1,n(g.water))*100)}%"></span></div><div class="water-add"><input id="waterAmount" type="number" min="1" inputmode="numeric" placeholder="bijv. 200"><span>ml</span><button class="meal-add" id="waterAdd" aria-label="Water toevoegen">＋</button></div>${waterEntries(iso).length?`<div class="water-log">${[...waterEntries(iso)].reverse().slice(0,8).map(w=>`<div><span>${esc(w.time)} · ${f(w.ml)} ml</span><button class="mini-delete" data-delwater="${w.id}" data-date="${iso}">×</button></div>`).join('')}</div>`:''}</div>
    <div class="card"><div class="section-title"><h2>Activiteit</h2><span>👟</span></div><div class="metric"><span>Stappen</span><b>${f(a.steps)} / ${f(g.steps)}</b></div><div class="metric"><span>Actieve kcal</span><b>${f(a.activeKcal)}</b></div><button class="secondary" id="activityEdit">Bewerken</button></div></section>`;
}
function mealCard(iso,mm){const items=entriesFor(iso,mm[0]),x=macros(items),plans=plannedForDate(iso).filter(p=>p.meal===mm[0]&&p.status!=='cancelled');return `<div class="card meal-card"><div><h3>${mm[2]} ${mm[1]}</h3><div><b>${f(x.kcal)} kcal gegeten</b></div><div class="macro-line">${f(x.protein,0)}g eiwit · ${f(x.carbs,0)}g KH · ${f(x.fat,0)}g vet</div>${plans.length?`<div class="planned-note">📌 ${plans.length} gepland · ${f(macros(plans.flatMap(p=>p.items)).kcal)} kcal</div>`:''}${items.length?`<button class="meal-edit-link" data-editloggedmeal="${mm[0]}" data-date="${iso}">Bewerken</button>`:''}</div><button class="meal-add" data-mealadd="${mm[0]}" data-date="${iso}">＋</button></div>`;}

function renderAgenda(){
  const selected=route.params.date||todayISO(),days=weekDates(selected),wk=weekStartISO(selected),g=weekGoal(selected),fast=isFasting(selected),plans=plannedForDate(selected),ws=(state.workouts||[]).filter(w=>w.date===selected).sort((a,b)=>(a.time||'').localeCompare(b.time||''));
  const end=days[6];setHeader(`Agenda · week ${weekNumber(selected)}`,`<button class="icon-btn" id="weekPrev">‹</button><button class="icon-btn" id="weekNext">›</button>`);
  return `<section class="section"><div class="week-title"><div><b>${fmtDate(wk)} – ${fmtDate(end)}</b><div class="subtle">Tik een dag aan om te plannen</div></div><button class="ghost-btn" id="weekSetup">Weekdoelen</button></div>
    <div class="week-strip">${days.map(d=>{const dt=dateObj(d),selectedCls=d===selected?'selected':'',today=d===todayISO()?'today-dot':'',has=dayAgendaItems(d).length||dayMacros(d).kcal>0,moon=isFasting(d);return `<button class="week-day ${selectedCls}" data-weekday="${d}"><span>${['ma','di','wo','do','vr','za','zo'][(dt.getDay()+6)%7]}</span><b>${dt.getDate()}</b><small>${moon?'🌙':has?'●':'○'}</small><i class="${today}"></i></button>`}).join('')}</div></section>
    ${g?`<section class="section card week-goal-summary"><div class="section-title"><h2>Weekdoel</h2><span class="badge">start ${g.startWeight?f(g.startWeight,1)+' kg':'gewicht —'}</span></div><div class="goal-inline"><span>${f(g.kcal)} kcal</span><span>P ${f(g.protein)}g</span><span>KH ${f(g.carbs)}g</span><span>V ${f(g.fat)}g</span></div></section>`:`<section class="section warning-box">Voor deze week zijn nog geen doelen ingesteld. <button class="secondary" id="weekSetupInline">Week instellen</button></section>`}
    <section class="section"><div class="selected-day-head"><div><h2>${fmtDate(selected,true)}</h2><div class="subtle">${selected===todayISO()?'Vandaag · ':''}${fast?'Vastendag':'Normale dag'}</div></div><label class="fast-toggle"><span>🌙 Vastendag</span><input id="fastToggle" type="checkbox" ${fast?'checked':''}></label></div></section>
    <section class="section"><div class="section-title"><h2>Maaltijden</h2><button class="primary" id="planMeal">＋ Maaltijd</button></div>${plans.length?`<div class="list">${plans.map(planRow).join('')}</div>`:`<div class="card empty">Nog geen maaltijden gepland.</div>`}</section>
    <section class="section"><div class="section-title"><h2>Training & activiteit</h2><button class="primary" id="planWorkout">＋ Training</button></div>${ws.length?`<div class="list">${ws.map(workoutRow).join('')}</div>`:`<div class="card empty">Nog geen training gepland.</div>`}<div class="card" style="margin-top:10px"><div class="row"><div><b>👟 Dagactiviteit</b><div class="meta">Stappen en actieve kcal</div></div><button class="secondary" id="agendaActivity">Bewerken</button></div></div></section>`;
}
function planRow(p){const mm=mealMeta(p.meal),x=macros(p.items);return `<div class="list-item"><div class="row"><div><h3>${mm[2]} ${esc(p.name||mm[1])}</h3><div class="meta">${p.time?esc(p.time)+' · ':''}${f(x.kcal)} kcal · P ${f(x.protein)}g · ${p.status==='completed'?'✓ gegeten':'gepland'}</div></div><span class="badge ${p.status==='completed'?'':'warn'}">${p.status==='completed'?'gedaan':'gepland'}</span></div><div class="form-actions" style="margin-top:10px">${p.status!=='completed'?`<button class="secondary" data-eatplan="${p.id}">Aanpassen & eten</button>`:''}<button class="danger-btn" data-delplan="${p.id}">Verwijderen</button></div></div>`;}
function workoutRow(w){return `<div class="list-item"><div class="row"><div><h3>${w.type==='kickboksen'?'🥊':'🏋️'} ${esc(w.title)}</h3><div class="meta">${esc(w.time||'tijd n.v.t.')} · ${f(w.duration)} min · ${esc(w.intensity||'')}</div></div><span class="badge">${esc(w.status||'gepland')}</span></div><div class="form-actions" style="margin-top:10px">${w.status!=='voltooid'?`<button class="secondary" data-completeworkout="${w.id}">Voltooid</button>`:''}<button class="secondary" data-editworkout="${w.id}">Bewerken</button><button class="danger-btn" data-delworkout="${w.id}">Verwijderen</button></div></div>`;}

function renderAddStart(){const iso=route.params.date||todayISO(),mode=route.params.mode||'actual';setHeader(mode==='planned'?`Maaltijd plannen · ${fmtDate(iso)}`:`Toevoegen · ${fmtDate(iso)}`);return `<section class="section"><div class="section-title"><h2>${mode==='planned'?'Kies gepland maaltijdmoment':'Kies maaltijdmoment'}</h2></div><div class="grid two">${mealsForDate(iso).map(m=>`<button class="category-card" data-startmeal="${m[0]}" data-date="${iso}" data-mode="${mode}"><span class="cat-icon">${m[2]}</span><b>${m[1]}</b><span class="subtle">${mode==='planned'?'Vooruit plannen':'Live samenstellen'}</span></button>`).join('')}</div></section><section class="section"><div class="section-title"><h2>Snel</h2></div><div class="grid two"><button class="category-card" data-go="recipes"><span class="cat-icon">⭐</span><b>Eigen recepten</b><span class="subtle">Herbruikbare combinaties</span></button><button class="category-card" id="recentStart"><span class="cat-icon">🕘</span><b>Recente producten</b><span class="subtle">Recent gebruikt</span></button></div></section>`;}
function startDraft(meal,iso=todayISO(),mode='actual',items=[]){state.draft={id:uid('draft'),date:iso,meal,mode,items:clone(items),createdAt:Date.now()};save();routeTo('builder');}
function draft(){return state.draft;}
function renderBuilder(){if(!draft()){setTimeout(()=>routeTo('add'),0);return '';}const d=draft();setHeader(`${mealMeta(d.meal)[2]} ${mealMeta(d.meal)[1]} · ${d.mode==='planned'?'plannen':'registreren'}`,`<button class="ghost-btn" id="cancelDraft">Annuleer</button>`);const counts={};d.items.forEach(i=>{const p=productById(i.productId);if(p)counts[p.category]=(counts[p.category]||0)+1;});const cats=Object.keys(CATEGORY_META).filter(c=>allProducts().some(p=>p.category===c));return `<section class="section"><div class="section-title"><h2>Kies categorie</h2><span class="badge">🛒 ${d.items.length}</span></div><div class="category-grid">${cats.map(c=>{const [ico,label]=CATEGORY_META[c];return `<button class="category-card" data-cat="${esc(c)}"><span class="cat-icon">${ico}</span><b>${label}</b><span class="subtle">${counts[c]?`✓ ${counts[c]} gekozen`:`${allProducts().filter(p=>p.category===c).length} producten`}</span></button>`}).join('')}</div></section>${d.items.length?`<div class="sticky-action"><button class="primary" style="width:100%" id="reviewCart">🛒 Bekijk selectie · ${d.items.length}</button></div>`:''}`;}
function filterAllowed(ps){return ps.filter(p=>!(/snoep|chocolade/i.test(p.name)&&p.category!=='Groenten'));}
function productRow(p){const ex=draft()?.items.find(i=>i.productId===p.id),fav=state.favorites.includes(p.id);return `<div class="product-row" data-product-row="${p.id}"><div class="product-head"><input type="checkbox" data-check="${p.id}" ${ex?'checked':''}><div class="product-main"><b>${p.brand?esc(p.brand)+' · ':''}${esc(p.name)}</b><div class="meta">${esc(p.state||'')} · ${f(p.kcal)} kcal · ${f(p.protein,1)}g eiwit /100${p.unit}</div></div><button class="icon-btn" data-fav="${p.id}">${fav?'★':'☆'}</button></div><div class="amount-wrap ${ex?'':'hidden'}" data-amountwrap="${p.id}"><input type="number" min="0" step="0.1" inputmode="decimal" data-amount="${p.id}" value="${ex?ex.amount:''}" placeholder="hoeveel"><span>${p.unit}</span><div style="flex:1"><div class="conversion-note ${ex&&conversionText(p,ex.amount)?'':'hidden'}" data-conv="${p.id}">${ex?conversionText(p,ex.amount):''}</div></div></div></div>`;}
function renderBuilderCategory(){if(!draft())return '';const cat=route.params.category,ps=filterAllowed(allProducts().filter(p=>p.category===cat));setHeader(`${CATEGORY_META[cat]?.[0]||'•'} ${cat}`,`<button class="ghost-btn" id="toBuilder">Categorieën</button>`);return `<div class="toolbar"><input id="productSearch" class="search" placeholder="Zoek in ${esc(cat)}"><button class="icon-btn" id="showFav">★</button></div><div class="product-list">${ps.map(productRow).join('')}</div><div class="sticky-action"><button class="primary" style="width:100%" id="addSelected">Toevoegen</button></div>`;}
function renderCart(){if(!draft())return '';const d=draft(),x=macros(d.items);setHeader(`Controle · ${mealMeta(d.meal)[1]}`,`<button class="ghost-btn" id="backBuilder">Categorieën</button>`);return `<section class="section card"><div class="section-title"><h2>🛒 ${mealMeta(d.meal)[1]}</h2><span class="badge">${d.mode==='planned'?'gepland':'werkelijk'}</span></div>${d.items.map(i=>`<div class="cart-line"><div><b>${esc(i.name)}</b><br><small>${f(i.amount,1)} ${i.unit} · ${f(i.snapshot.kcal)} kcal</small></div><button class="icon-btn" data-edititem="${i.productId}">✎</button><button class="icon-btn" data-removeitem="${i.productId}">×</button></div>`).join('')}<div class="cart-total"><div class="metric"><span>Totaal</span><b>${f(x.kcal)} kcal</b></div><div class="metric"><span>Eiwit</span><b>${f(x.protein,1)} g</b></div><div class="metric"><span>Koolhydraten</span><b>${f(x.carbs,1)} g</b></div><div class="metric"><span>Vet</span><b>${f(x.fat,1)} g</b></div></div></section>${d.mode==='planned'?`<section class="section card"><div class="field"><label>Tijd (optioneel)</label><input id="planTime" type="time" value="${esc(d.time||'')}"></div></section>`:''}<section class="section card"><div class="field"><label>Eigen recept bewaren (optioneel)</label><input id="recipeName" placeholder="Bijv. standaard ontbijt"></div></section><div class="form-actions"><button class="secondary" id="addMore">Product toevoegen</button><button class="primary" id="saveMeal">${d.mode==='planned'?'In agenda zetten':'Maaltijd opslaan'}</button></div>`;}
function addSelectedToDraft(){const sel=[...document.querySelectorAll('[data-check]:checked')];if(!sel.length)return toast('Selecteer minimaal één product');for(const ch of sel){const id=ch.dataset.check,p=productById(id),amount=n(document.querySelector(`[data-amount="${id}"]`)?.value);if(amount<=0)return toast(`Vul een hoeveelheid in voor ${p.name}`);const item={productId:id,name:(p.brand?p.brand+' · ':'')+p.name,amount,unit:p.unit,snapshot:amountSnapshot(p,amount),addedAt:Date.now()};state.draft.items=state.draft.items.filter(x=>x.productId!==id);state.draft.items.push(item);state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,30);}save();toast('Toegevoegd');routeTo('builder');}
function saveDraftMeal(){const d=draft();if(!d?.items.length)return toast('Voeg eerst producten toe');const rn=(document.getElementById('recipeName')?.value||'').trim();if(rn)state.recipes.push({id:uid('recipe'),name:rn,items:clone(d.items),createdAt:Date.now()});if(d.mode==='planned'){if(d.sourcePlanId)state.plannedMeals=state.plannedMeals.filter(p=>p.id!==d.sourcePlanId);state.plannedMeals.push({id:uid('plan'),date:d.date,meal:d.meal,time:document.getElementById('planTime')?.value||d.time||'',name:rn||mealMeta(d.meal)[1],items:clone(d.items),status:'planned',createdAt:Date.now()});state.draft=null;save();toast('Maaltijd ingepland');routeTo('agenda',{date:d.date});return;}const day=getDay(d.date);day[d.meal]=(day[d.meal]||[]).concat(d.items.map(i=>({...i,entryId:uid('entry')})));if(d.sourcePlanId){const p=state.plannedMeals.find(x=>x.id===d.sourcePlanId);if(p)p.status='completed';}state.draft=null;save();toast('Maaltijd opgeslagen');routeTo('home',{date:d.date});}

function renderWeight(){setHeader('Gewicht',`<button class="primary" id="addWeight">＋ Meting</button>`);const ws=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date)),latest=ws.at(-1);return `<section class="section grid three"><div class="card"><div class="subtle">Laatste</div><b style="font-size:23px">${latest?f(latest.kg,1)+' kg':'—'}</b></div><div class="card"><div class="subtle">7 dagen</div><b style="font-size:23px">${weightDiff(ws,7)===null?'—':signed(weightDiff(ws,7))+' kg'}</b></div><div class="card"><div class="subtle">30 dagen</div><b style="font-size:23px">${weightDiff(ws,30)===null?'—':signed(weightDiff(ws,30))+' kg'}</b></div></section><section class="section card"><div class="section-title"><h2>7-daags gemiddelde</h2></div>${weightChart(ws)}</section><section class="section"><div class="list">${[...ws].reverse().map(w=>`<div class="list-item"><div class="row"><b>${fmtDate(w.date)}</b><span>${f(w.kg,1)} kg</span></div><div class="form-actions"><button class="danger-btn" data-delweight="${w.date}">Verwijderen</button></div></div>`).join('')}</div></section>`;}
function weightDiff(ws,days){if(ws.length<2)return null;const latest=ws.at(-1),cut=dateObj(latest.date);cut.setDate(cut.getDate()-days);const earlier=[...ws].reverse().find(w=>dateObj(w.date)<=cut);return earlier?latest.kg-earlier.kg:null;}
function signed(v){return(v>0?'+':'')+f(v,1);}
function movingAverage(ws,i){const z=ws.slice(Math.max(0,i-6),i+1);return z.reduce((s,x)=>s+n(x.kg),0)/z.length;}
function weightChart(ws){if(!ws.length)return `<div class="empty">Nog geen gewichtsdata.</div>`;const pts=ws.slice(-90),vals=pts.map((x,i)=>movingAverage(pts,i));return svgLine(vals);}
function svgLine(vals){if(!vals.length)return '';const W=600,H=200,p=25,min=Math.min(...vals),max=Math.max(...vals),span=Math.max(.1,max-min),xy=vals.map((v,i)=>[p+(W-2*p)*(i/Math.max(1,vals.length-1)),H-p-(H-2*p)*((v-min)/span)]),path=xy.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join(' ');return `<svg class="svg-chart" viewBox="0 0 ${W} ${H}"><line class="chart-grid" x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}"/><path class="chart-line" d="${path}"/></svg>`;}

function renderMore(){setHeader('Meer');const items=[['products','🥕','Producten','Bekijken en bewerken'],['recipes','⭐','Eigen recepten','Opgeslagen combinaties'],['trends','⌁','Trends','Voeding en gewicht'],['goals','◎','Weekdoelen','Macro’s en weekstart'],['history','🕘','Historie','Daglogs terugkijken'],['settings','⚙','Instellingen','Back-up en PWA']];return `<div class="more-grid">${items.map(i=>`<button class="more-btn" data-go="${i[0]}"><span class="ico">${i[1]}</span><b>${i[2]}</b><span class="subtle">${i[3]}</span></button>`).join('')}</div>`;}
function productBrowseRow(p){return `<div class="product-row"><div class="product-head"><div class="product-main"><b>${p.brand?esc(p.brand)+' · ':''}${esc(p.name)}</b><div class="meta">${esc(p.category)} · ${esc(p.state||'')} · ${f(p.kcal)} kcal · P ${f(p.protein,1)} /100${p.unit}</div>${p.edited?`<span class="badge">aangepast</span>`:''}</div><button class="secondary" data-editproduct="${p.id}">Bewerken</button></div></div>`;}
function renderProducts(){setHeader('Producten',`<button class="primary" id="newProduct">＋ Product</button>`);return `<div class="toolbar"><input id="allProductSearch" class="search" placeholder="Zoek product, merk of categorie"><span class="badge">${allProducts().length}</span></div><div id="allProductList" class="product-list">${allProducts().map(productBrowseRow).join('')}</div>`;}
function renderRecipes(){setHeader('Eigen recepten');return `<section class="section">${state.recipes.length?`<div class="list">${state.recipes.map(r=>`<div class="list-item"><div class="row"><div><h3>${esc(r.name)}</h3><div class="meta">${r.items.length} ingrediënten · ${f(macros(r.items).kcal)} kcal</div></div><button class="secondary" data-userecipe="${r.id}">Gebruiken</button></div><div class="form-actions"><button class="danger-btn" data-delrecipe="${r.id}">Verwijderen</button></div></div>`).join('')}</div>`:`<div class="card empty">Nog geen eigen recepten.</div>`}</section>`;}
function renderTrends(){setHeader('Trends');const days=n(route.params.days,30),end=todayISO(),start=addDaysISO(end,-days+1),dates=Array.from({length:days},(_,i)=>addDaysISO(start,i)),av=dates.reduce((a,d)=>{const m=dayMacros(d);a.kcal+=m.kcal;a.protein+=m.protein;return a;},{kcal:0,protein:0});return `<section class="section"><div class="toolbar">${[7,30,90].map(d=>`<button class="${days===d?'primary':'secondary'}" data-days="${d}">${d} dagen</button>`).join('')}</div><div class="grid two"><div class="card"><div class="subtle">Gem. kcal</div><b style="font-size:24px">${f(av.kcal/days)}</b></div><div class="card"><div class="subtle">Gem. eiwit</div><b style="font-size:24px">${f(av.protein/days)} g</b></div></div></section><section class="section card"><div class="section-title"><h2>Gewichtstrend</h2></div>${weightChart(state.weights.filter(w=>w.date>=start))}</section>`;}
function renderGoals(){const iso=route.params.date||todayISO(),wk=weekStartISO(iso),g={...effectiveGoals(iso)};setHeader(`Weekdoelen · week ${weekNumber(iso)}`);return `<section class="section card"><div class="form-grid"><div class="field"><label>Week start</label><input value="${wk}" disabled></div>${goalField('kcal','Caloriedoel per dag','kcal',g.kcal)}${goalField('protein','Eiwit','g',g.protein)}${goalField('carbs','Koolhydraten','g',g.carbs)}${goalField('fat','Vet','g',g.fat)}${goalField('fiber','Vezels','g',g.fiber)}${goalField('water','Water','ml',g.water)}${goalField('steps','Stappen','',g.steps)}${goalField('startWeight','Startgewicht van deze week','kg',weekGoal(iso)?.startWeight??'')}</div><div class="form-actions" style="margin-top:14px"><button class="primary" id="saveWeekGoals">Weekdoelen opslaan</button></div></section><section class="section card"><div class="section-title"><h2>Energie-instellingen</h2></div><div class="form-grid">${goalField('restingBurn','Conservatieve rustverbranding','kcal',state.goals.restingBurn)}${goalField('activeDeduction','Correctie actieve kcal','%',state.goals.activeDeduction)}</div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="saveEnergySettings">Opslaan</button></div></section>`;}
function goalField(id,label,unit,val){return `<div class="field"><label>${label}${unit?' ('+unit+')':''}</label><input id="goal_${id}" type="number" step="0.1" value="${val??''}"></div>`;}
function renderHistory(){setHeader('Historie');const dates=[...new Set([...Object.keys(state.logs),...state.plannedMeals.map(p=>p.date)])].sort().reverse();return `<section class="section">${dates.length?`<div class="list">${dates.map(iso=>{const m=dayMacros(iso),p=plannedMacros(iso);return `<button class="list-item" style="text-align:left;width:100%" data-historydate="${iso}"><div class="row"><b>${fmtDate(iso)}</b><span>${f(m.kcal)} kcal</span></div><div class="meta">Gepland ${f(p.kcal)} kcal · P ${f(m.protein)}g</div></button>`}).join('')}</div>`:`<div class="card empty">Nog geen historie.</div>`}</section>`;}
function renderSettings(){setHeader('Instellingen');return `<section class="section card"><div class="section-title"><h2>Lokale gegevens</h2></div><p class="subtle">Alles staat lokaal op dit apparaat. Maak geregeld een back-up.</p><div class="form-actions"><button class="primary" id="exportData">Back-up exporteren</button><label class="secondary">Back-up importeren<input id="importData" type="file" accept="application/json" hidden></label></div></section><section class="section card"><div class="section-title"><h2>PWA / offline</h2></div><div id="pwaState" class="ok-box">Status controleren…</div></section>`;}

function modal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').classList.add('show');}
function closeModal(){document.getElementById('modal').classList.remove('show');document.getElementById('modalContent').innerHTML='';}
function v(id){return document.getElementById(id)?.value??'';}
function productForm(existing=null){const p=existing?clone(existing):{category:'Zuivel',name:'',brand:'',state:'ready-to-use',unit:'g',kcal:0,protein:0,carbs:0,fat:0,fiber:0,sugars:0,satFat:0,salt:0,source:'',sourceStatus:'Handmatig toegevoegd',note:''},isEdit=!!existing;modal(`<h2>${isEdit?'Product bewerken':'Eigen product toevoegen'}</h2><div class="form-grid"><div class="field"><label>Categorie</label><select id="p_cat">${Object.keys(CATEGORY_META).map(c=>`<option value="${esc(c)}" ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Productnaam</label><input id="p_name" value="${esc(p.name)}"></div><div class="field"><label>Merk</label><input id="p_brand" value="${esc(p.brand||'')}"></div><div class="field"><label>Toestand</label><input id="p_state" value="${esc(p.state||'')}"></div><div class="field"><label>Eenheid</label><select id="p_unit"><option value="g" ${p.unit==='g'?'selected':''}>g</option><option value="ml" ${p.unit==='ml'?'selected':''}>ml</option></select></div><div class="grid two">${['kcal','protein','carbs','fat','fiber','sugars','satFat','salt'].map(k=>`<div class="field"><label>${{kcal:'kcal',protein:'Eiwit',carbs:'KH',fat:'Vet',fiber:'Vezels',sugars:'Suikers',satFat:'Verzadigd vet',salt:'Zout'}[k]} /100</label><input id="p_${k}" type="number" step="0.01" value="${p[k]??0}"></div>`).join('')}</div><div class="field"><label>Bron/notitie</label><textarea id="p_note">${esc(p.note||'')}</textarea></div></div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="mCancel">Annuleer</button>${isEdit&&!p.custom?`<button class="secondary" id="pReset">Herstel standaard</button>`:''}<button class="primary" id="pSave">Opslaan</button></div>`);document.getElementById('mCancel').onclick=closeModal;if(document.getElementById('pReset'))document.getElementById('pReset').onclick=()=>{delete state.productOverrides[p.id];save();closeModal();render();toast('Standaard hersteld');};document.getElementById('pSave').onclick=()=>{const name=v('p_name').trim();if(!name)return toast('Vul een productnaam in');const data={category:v('p_cat'),name,brand:v('p_brand').trim(),state:v('p_state').trim(),unit:v('p_unit'),kcal:n(v('p_kcal')),protein:n(v('p_protein')),carbs:n(v('p_carbs')),fat:n(v('p_fat')),fiber:n(v('p_fiber')),sugars:n(v('p_sugars')),satFat:n(v('p_satFat')),salt:n(v('p_salt')),note:v('p_note').trim(),sourceStatus:'Handmatig aangepast'};if(isEdit){if(p.custom){const i=state.foods.findIndex(x=>x.id===p.id);if(i>=0)state.foods[i]={...state.foods[i],...data,custom:true};else state.foods.push({...p,...data,custom:true});}else state.productOverrides[p.id]={...data,edited:true};}else state.foods.push({id:uid('custom'),...data,halalStatus:'needs verification',labelRule:'',source:'',custom:true});save();closeModal();render();toast(isEdit?'Product aangepast':'Product toegevoegd');};}

function loggedMealModal(iso,meal){const items=entriesFor(iso,meal),mm=mealMeta(meal);if(!items.length)return toast('Deze maaltijd bevat nog geen ingrediënten');modal(`<h2>${mm[2]} ${mm[1]} bewerken</h2><p class="subtle">Pas de werkelijk gegeten hoeveelheid aan of verwijder een ingrediënt. De oorspronkelijke voedingswaardes blijven als basis behouden.</p><div class="logged-meal-list">${items.map((i,idx)=>`<div class="logged-edit-row"><div><b>${esc(i.name)}</b><div class="meta">${f(i.snapshot.kcal)} kcal</div></div><div class="logged-amount"><input id="logged_${idx}" type="number" min="0.1" step="0.1" value="${i.amount}"><span>${i.unit}</span></div><button class="mini-delete" data-modaldelete="${i.entryId}">×</button></div>`).join('')}</div><div class="form-actions"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="loggedSave">Wijzigingen opslaan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.querySelectorAll('[data-modaldelete]').forEach(btn=>btn.onclick=()=>{const day=getDay(iso);day[meal]=(day[meal]||[]).filter(x=>x.entryId!==btn.dataset.modaldelete);save();closeModal();render();toast('Ingrediënt verwijderd');});document.getElementById('loggedSave').onclick=()=>{const day=getDay(iso);day[meal]=(day[meal]||[]).map((i,idx)=>{const amount=n(v(`logged_${idx}`));if(amount<=0)return i;const old=n(i.amount);const ratio=old>0?amount/old:1;const snap={};for(const k of ['kcal','protein','carbs','fat','fiber','sugars','satFat','salt'])snap[k]=n(i.snapshot?.[k])*ratio;return {...i,amount,snapshot:snap};});save();closeModal();render();toast('Maaltijd aangepast');};}

function workoutForm(existing=null,date=currentDate()){const w=existing||{date,time:'',title:'',type:'krachttraining',duration:60,intensity:'gemiddeld',status:'gepland',note:''};modal(`<h2>${existing?'Training bewerken':'Training plannen'}</h2><div class="form-grid"><div class="field"><label>Datum</label><input id="w_date" type="date" value="${w.date||date}"></div><div class="field"><label>Tijd</label><input id="w_time" type="time" value="${esc(w.time||'')}"></div><div class="field"><label>Titel</label><input id="w_title" value="${esc(w.title||'')}"></div><div class="field"><label>Type</label><select id="w_type"><option ${w.type==='krachttraining'?'selected':''}>krachttraining</option><option ${w.type==='kickboksen'?'selected':''}>kickboksen</option><option ${w.type==='wandelen/stappen'?'selected':''}>wandelen/stappen</option><option ${w.type==='overig'?'selected':''}>overig</option></select></div><div class="field"><label>Duur (min)</label><input id="w_duration" type="number" value="${n(w.duration,60)}"></div><div class="field"><label>Intensiteit</label><select id="w_intensity"><option>laag</option><option ${w.intensity==='gemiddeld'?'selected':''}>gemiddeld</option><option ${w.intensity==='hoog'?'selected':''}>hoog</option></select></div><div class="field"><label>Notitie</label><textarea id="w_note">${esc(w.note||'')}</textarea></div></div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="wSave">Opslaan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('wSave').onclick=()=>{const item={id:existing?.id||uid('workout'),date:v('w_date'),time:v('w_time'),title:v('w_title').trim()||'Training',type:v('w_type'),duration:n(v('w_duration')),intensity:v('w_intensity'),status:existing?.status||'gepland',note:v('w_note')};state.workouts=state.workouts.filter(x=>x.id!==item.id);state.workouts.push(item);save();closeModal();render();toast('Training opgeslagen');};}
function activityModal(iso){const a=activityFor(iso);modal(`<h2>Activiteit · ${fmtDate(iso)}</h2><div class="form-grid"><div class="field"><label>Stappen</label><input id="a_steps" type="number" value="${a.steps}"></div><div class="field"><label>Smartwatch actieve kcal</label><input id="a_kcal" type="number" value="${a.activeKcal}"></div></div><div class="form-actions"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="aSave">Opslaan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('aSave').onclick=()=>{state.activity[iso]={steps:n(v('a_steps')),activeKcal:n(v('a_kcal'))};save();closeModal();render();};}
function weightModal(){const iso=currentDate(),ex=state.weights.find(w=>w.date===iso);modal(`<h2>Gewicht · ${fmtDate(iso)}</h2><div class="field"><label>Gewicht (kg)</label><input id="kg" type="number" step="0.05" value="${ex?.kg||''}"></div><div class="form-actions"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="kgSave">Opslaan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('kgSave').onclick=()=>{const kg=n(v('kg'));if(kg<=0)return toast('Vul een geldig gewicht in');state.weights=state.weights.filter(w=>w.date!==iso);state.weights.push({date:iso,kg});state.weights.sort((a,b)=>a.date.localeCompare(b.date));save();closeModal();render();};}
function weekSetupModal(iso){const wk=weekStartISO(iso),old=weekGoal(iso)||effectiveGoals(iso),days=weekDates(iso);modal(`<h2>Week ${weekNumber(iso)} instellen</h2><p class="subtle">${fmtDate(wk)} – ${fmtDate(days[6])}. Deze doelen blijven bij deze week horen.</p><div class="form-grid">${goalField('wk_kcal','Calorieën per dag','kcal',old.kcal)}${goalField('wk_protein','Eiwit per dag','g',old.protein)}${goalField('wk_carbs','Koolhydraten per dag','g',old.carbs)}${goalField('wk_fat','Vet per dag','g',old.fat)}${goalField('wk_weight','Startgewicht','kg',weekGoal(iso)?.startWeight??'')}<div class="field"><label>Sunnah-vastendagen deze week</label><div class="week-checks">${days.map(d=>`<label><input type="checkbox" data-fastday="${d}" ${isFasting(d)?'checked':''}> ${fmtDate(d)}</label>`).join('')}</div></div></div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="mCancel">Later</button><button class="primary" id="wkSave">Week starten / opslaan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('wkSave').onclick=()=>{state.weekGoals[wk]={kcal:n(v('goal_wk_kcal')),protein:n(v('goal_wk_protein')),carbs:n(v('goal_wk_carbs')),fat:n(v('goal_wk_fat')),fiber:n(old.fiber||30),water:n(old.water||2500),steps:n(old.steps||10000),startWeight:v('goal_wk_weight')?n(v('goal_wk_weight')):null,createdAt:Date.now()};days.forEach(d=>{state.fastingDays[d]=!!document.querySelector(`[data-fastday="${d}"]`)?.checked;});if(state.weekGoals[wk].startWeight){state.weights=state.weights.filter(w=>w.date!==wk);state.weights.push({date:wk,kg:state.weekGoals[wk].startWeight});state.weights.sort((a,b)=>a.date.localeCompare(b.date));}save();closeModal();render();toast('Week opgeslagen');};}
function maybePromptWeek(){if(!['home','agenda'].includes(route.name))return;const iso=currentDate(),wk=weekStartISO(iso);if(wk!==weekStartISO(todayISO())||state.weekGoals[wk])return;const key='balance.weekPrompt.'+wk;if(sessionStorage.getItem(key))return;sessionStorage.setItem(key,'1');setTimeout(()=>weekSetupModal(iso),250);}
function toggleFast(iso,on){const hasNormal=plannedForDate(iso).some(p=>NORMAL_MEALS.some(m=>m[0]===p.meal))||NORMAL_MEALS.some(m=>entriesFor(iso,m[0]).length);if(on&&hasNormal&&!confirm('Deze dag bevat al gewone maaltijden. Ze worden niet verwijderd, maar Suhoor/Futoor worden de primaire maaltijdmomenten. Doorgaan?')){render();return;}state.fastingDays[iso]=on;save();render();}
function useRecipe(r){if(!r)return;const iso=route.params.date||todayISO(),mode=route.params.mode||'actual';modal(`<h2>${esc(r.name)}</h2><p class="subtle">Kies maaltijdmoment.</p><div class="grid two">${mealsForDate(iso).map(m=>`<button class="category-card" data-recipemeal="${m[0]}"><span class="cat-icon">${m[2]}</span><b>${m[1]}</b></button>`).join('')}</div>`);document.querySelectorAll('[data-recipemeal]').forEach(b=>b.onclick=()=>{closeModal();startDraft(b.dataset.recipemeal,iso,mode,r.items);});}

function bindDynamic(){
  const q=id=>document.getElementById(id);
  if(q('datePrev'))q('datePrev').onclick=()=>shiftHome(-1);if(q('dateNext'))q('dateNext').onclick=()=>shiftHome(1);
  if(q('weekPrev'))q('weekPrev').onclick=()=>routeTo('agenda',{date:addDaysISO(weekStartISO(currentDate()),-7)});if(q('weekNext'))q('weekNext').onclick=()=>routeTo('agenda',{date:addDaysISO(weekStartISO(currentDate()),7)});
  if(q('weekSetup'))q('weekSetup').onclick=()=>weekSetupModal(currentDate());if(q('weekSetupInline'))q('weekSetupInline').onclick=()=>weekSetupModal(currentDate());
  if(q('fastToggle'))q('fastToggle').onchange=e=>toggleFast(currentDate(),e.target.checked);
  if(q('planMeal'))q('planMeal').onclick=()=>routeTo('add',{date:currentDate(),mode:'planned'});if(q('planWorkout'))q('planWorkout').onclick=()=>workoutForm(null,currentDate());if(q('agendaActivity'))q('agendaActivity').onclick=()=>activityModal(currentDate());
  if(q('waterAdd'))q('waterAdd').onclick=()=>{const ml=n(v('waterAmount'));if(ml<=0)return toast('Vul het aantal ml in');const iso=currentDate();if(!state.waterLogs[iso])state.waterLogs[iso]=[];state.waterLogs[iso].push({id:uid('water'),ml,time:fmtTime(new Date()),createdAt:Date.now()});save();render();toast(`${f(ml)} ml toegevoegd`);};
  if(q('activityEdit'))q('activityEdit').onclick=()=>activityModal(currentDate());
  if(q('cancelDraft'))q('cancelDraft').onclick=()=>{if(confirm('Huidige selectie wissen?')){state.draft=null;save();routeTo('home');}};
  if(q('toBuilder'))q('toBuilder').onclick=()=>routeTo('builder');if(q('reviewCart'))q('reviewCart').onclick=()=>routeTo('cart');if(q('backBuilder'))q('backBuilder').onclick=()=>routeTo('builder');if(q('addMore'))q('addMore').onclick=()=>routeTo('builder');if(q('addSelected'))q('addSelected').onclick=addSelectedToDraft;if(q('saveMeal'))q('saveMeal').onclick=saveDraftMeal;
  if(q('productSearch'))q('productSearch').oninput=()=>searchCategory(q('productSearch').value);if(q('showFav'))q('showFav').onclick=()=>document.querySelectorAll('[data-product-row]').forEach(r=>r.classList.toggle('hidden',!state.favorites.includes(r.dataset.productRow)));
  if(q('newProduct'))q('newProduct').onclick=()=>productForm();if(q('allProductSearch'))q('allProductSearch').oninput=()=>browseProducts(q('allProductSearch').value);
  if(q('addWeight'))q('addWeight').onclick=weightModal;
  if(q('saveWeekGoals'))q('saveWeekGoals').onclick=()=>{const iso=currentDate(),wk=weekStartISO(iso),old=effectiveGoals(iso);state.weekGoals[wk]={...state.weekGoals[wk],kcal:n(v('goal_kcal')),protein:n(v('goal_protein')),carbs:n(v('goal_carbs')),fat:n(v('goal_fat')),fiber:n(v('goal_fiber')),water:n(v('goal_water')),steps:n(v('goal_steps')),startWeight:v('goal_startWeight')?n(v('goal_startWeight')):null};save();toast('Weekdoelen opgeslagen');render();};
  if(q('saveEnergySettings'))q('saveEnergySettings').onclick=()=>{state.goals.restingBurn=n(v('goal_restingBurn'));state.goals.activeDeduction=n(v('goal_activeDeduction'));save();toast('Energie-instellingen opgeslagen');};
  if(q('exportData'))q('exportData').onclick=exportData;if(q('importData'))q('importData').onchange=importData;if(q('pwaState'))updatePWAState();
  if(q('recentStart'))q('recentStart').onclick=()=>{const iso=route.params.date||todayISO(),mode=route.params.mode||'actual';startDraft(mealsForDate(iso)[0][0],iso,mode);};
}
function searchCategory(term){const t=term.trim().toLowerCase();document.querySelectorAll('[data-product-row]').forEach(r=>{const p=productById(r.dataset.productRow);r.classList.toggle('hidden',!!t&&!`${p.name} ${p.brand} ${p.state}`.toLowerCase().includes(t));});}
function browseProducts(term){const t=term.trim().toLowerCase(),ps=allProducts().filter(p=>!t||`${p.name} ${p.brand} ${p.category} ${p.state}`.toLowerCase().includes(t));document.getElementById('allProductList').innerHTML=ps.map(productBrowseRow).join('');}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`balance-backup-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function importData(e){const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!confirm('Huidige lokale data vervangen door deze back-up?'))return;state={...clone(DEFAULTS),...x,goals:{...DEFAULTS.goals,...(x.goals||{})}};save();toast('Back-up geïmporteerd');routeTo('home');}catch{toast('Ongeldig back-upbestand');}};r.readAsText(file);}
async function updatePWAState(){const el=document.getElementById('pwaState');try{const reg=await navigator.serviceWorker?.getRegistration();el.textContent=reg?'Offline service worker actief.':'Service worker wordt geregistreerd.';}catch{}}

document.addEventListener('click',e=>{const b=e.target.closest('button,[data-go],[data-weekday]');if(!b)return;
  if(b.dataset.go){routeTo(b.dataset.go);return;}if(b.dataset.weekday){routeTo('agenda',{date:b.dataset.weekday});return;}if(b.dataset.agendadate){routeTo('agenda',{date:b.dataset.agendadate});return;}if(b.dataset.addmealdate){routeTo('add',{date:b.dataset.addmealdate,mode:'actual'});return;}
  if(b.dataset.mealadd){startDraft(b.dataset.mealadd,b.dataset.date||currentDate(),'actual');return;}if(b.dataset.editloggedmeal){loggedMealModal(b.dataset.date||currentDate(),b.dataset.editloggedmeal);return;}if(b.dataset.startmeal){startDraft(b.dataset.startmeal,b.dataset.date||todayISO(),b.dataset.mode||'actual');return;}if(b.dataset.cat){routeTo('builderCategory',{category:b.dataset.cat});return;}
  if(b.dataset.fav){const id=b.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();return;}if(b.dataset.edititem){const p=productById(b.dataset.edititem);routeTo('builderCategory',{category:p.category});return;}if(b.dataset.removeitem){state.draft.items=state.draft.items.filter(i=>i.productId!==b.dataset.removeitem);save();render();return;}
  if(b.dataset.editproduct){productForm(productById(b.dataset.editproduct));return;}if(b.dataset.userecipe){useRecipe(state.recipes.find(r=>r.id===b.dataset.userecipe));return;}if(b.dataset.delrecipe){if(confirm('Recept verwijderen?')){state.recipes=state.recipes.filter(r=>r.id!==b.dataset.delrecipe);save();render();}return;}
  if(b.dataset.eatplan){const p=state.plannedMeals.find(x=>x.id===b.dataset.eatplan);if(p){state.draft={id:uid('draft'),date:p.date,meal:p.meal,mode:'actual',items:clone(p.items),sourcePlanId:p.id,createdAt:Date.now()};save();routeTo('cart');}return;}if(b.dataset.delplan){if(confirm('Geplande maaltijd verwijderen?')){state.plannedMeals=state.plannedMeals.filter(p=>p.id!==b.dataset.delplan);save();render();}return;}
  if(b.dataset.editworkout){workoutForm(state.workouts.find(x=>x.id===b.dataset.editworkout));return;}if(b.dataset.completeworkout){const w=state.workouts.find(x=>x.id===b.dataset.completeworkout);if(w){w.status='voltooid';save();render();}return;}if(b.dataset.delworkout){if(confirm('Training verwijderen?')){state.workouts=state.workouts.filter(x=>x.id!==b.dataset.delworkout);save();render();}return;}
  if(b.dataset.delweight){state.weights=state.weights.filter(w=>w.date!==b.dataset.delweight);save();render();return;}if(b.dataset.delwater){const iso=b.dataset.date;state.waterLogs[iso]=(state.waterLogs[iso]||[]).filter(w=>w.id!==b.dataset.delwater);save();render();toast('Waterinvoer verwijderd');return;}if(b.dataset.fastToggle){toggleFast(b.dataset.fastToggle,false);return;}if(b.dataset.days){route.params.days=n(b.dataset.days);render();return;}if(b.dataset.historydate){routeTo('home',{date:b.dataset.historydate});return;}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){const id=e.target.dataset.check;document.querySelector(`[data-amountwrap="${id}"]`)?.classList.toggle('hidden',!e.target.checked);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-amount]')){const id=e.target.dataset.amount,p=productById(id),el=document.querySelector(`[data-conv="${id}"]`),txt=conversionText(p,n(e.target.value));if(el){el.textContent=txt;el.classList.toggle('hidden',!txt);}}});
document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal();});
document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>routeTo(b.dataset.route,{date:b.dataset.route==='agenda'?todayISO():undefined}));
if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
const hash=location.hash.replace('#','');route={name:hash==='today'?'home':(hash||'home'),params:{}};render();
